mapper.select:
SELECT t.id, t.instance_id, t.node_id, t.node_order, t.node_name, i.biz_type, i.biz_no, i.biz_id, d.flow_name, i.start_user_id, u.nickname AS start_user_name, i.status AS instance_status, t.status, t.opinion, t.approve_time, t.create_time FROM wf_task t JOIN wf_instance i ON i.id = t.instance_id AND i.deleted = 0 LEFT JOIN wf_definition d ON d.id = i.definition_id AND d.deleted = 0 LEFT JOIN sys_user u ON u.id = i.start_user_id AND u.deleted = 0
t.deleted = 0 AND t.approver_id = #{approverId} AND t.status <> 'PENDING' AND t.status = 'PENDING' AND i.biz_no LIKE CONCAT('%', #{keyword}, '%') AND i.biz_type = #{bizType}
ORDER BY t.id DESC
